const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-122.555169, 40.190004);
  const startDate = '2020-08-25';
  const endDate = '2020-08-26'; // End date is exclusive

  // 2. Data Acquisition & Check
  // The question asks for 'mg/m^2', which implies a column density.
  // COPERNICUS/CAMS/NRT provides 'total_column_black_carbon_aerosol_mass_concentration'
  // with units kg m^-2, which aligns with the question's units after conversion.
  let collection = ee.ImageCollection('COPERNICUS/CAMS/NRT')
    .filterDate(startDate, endDate)
    .filterBounds(point);

  const initialSize = collection.size().getInfo();
  if (initialSize === 0) {
    console.log("No CAMS NRT images found for August 25, 2020.");
    console.log("C1");
    return;
  }
  console.log(`CAMS NRT Images found: ${initialSize}`);

  // Select the relevant band for total column black carbon
  // Unit for this band is kg m^-2
  collection = collection.select('total_column_black_carbon_aerosol_mass_concentration');

  // We expect one image for a specific date (daily average or forecast)
  const image = collection.mosaic(); // Use mosaic in case there are multiple images for the day, to get one result.

  // 3. Processing & Calculation
  // Reduce the region to get the black carbon concentration at the point.
  // Use a scale appropriate for CAMS data (often coarser resolution, e.g., 40km approx).
  const scale = 40000; // CAMS resolution is approximately 0.4 degrees (~40km at equator)

  const rawValue = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point,
    scale: scale,
    maxPixels: 1e9
  }).get('total_column_black_carbon_aerosol_mass_concentration').getInfo();

  if (rawValue === null || rawValue === undefined) {
    console.log("Calculation failed: Could not retrieve black carbon concentration.");
    console.log("C3");
    return;
  }

  // Convert kg/m^2 to mg/m^2
  // 1 kg = 1,000,000 mg
  const value_mg_per_m2 = rawValue * 1e6; // kg m^-2 to mg m^-2

  // Validate pixel count (implicitly done by reduceRegion, if value is not null, pixels were valid)
  // To explicitly check for valid pixels, we'd need to create a mask from the image.
  // Since CAMS data is model output, 'no valid pixels' due to cloud mask is not applicable.
  // If the value is retrieved, we assume valid data.

  // 4. Validation & Final Answer
  const threshold = 12; // mg/m^2

  console.log(`Black Carbon Concentrate (kg/m^2): ${rawValue.toFixed(6)}`);
  console.log(`Black Carbon Concentrate (mg/m^2): ${value_mg_per_m2.toFixed(2)}`);
  console.log(`Threshold: ${threshold} mg/m^2`);

  if (value_mg_per_m2 > threshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
